private static <T> T checkConversionResult(Class<T> type, Object result) {
    if (type == null) {
        // if the type is null, return the result as is
        @SuppressWarnings("unchecked")
        T temp = (T) result;
        return temp;
    }
    if (result == null) {
        // if the result is null and the type is not primitive, return null
        if (!type.isPrimitive()) {
            return null;
        }
        throw new ConversionException("Null value for primitive target type: " + type);
    }
    if (type.isInstance(result)) {
        return type.cast(result);
    }
    throw new ConversionException("Unsupported target type: " + type);
}

